package api

// The two larger operational pages live beside the shared shell to keep their
// markup reviewable without introducing a second rendering system.
const mission03Templates = `
{{define "automation"}}{{template "top" .}}
<header class="automation-hero"><div><p class="eyebrow">{{tr .Lang "automation_eyebrow"}}</p><h1>{{tr .Lang "automation_title"}}</h1><p class="lead">{{tr .Lang "automation_intro"}}</p><div class="automation-meta"><span class="badge {{if .ActiveRevision}}{{if .ActiveRevision.Paused}}paused{{else}}active{{end}}{{else}}pending{{end}}">{{if .ActiveRevision}}{{if .ActiveRevision.Paused}}{{tr .Lang "Paused"}}{{else}}{{tr .Lang "Active"}}{{end}}{{else}}{{tr .Lang "automation_not_active"}}{{end}}</span>{{if .ActiveRevision}}<span>{{tr .Lang "automation_revision"}} <strong>#{{.ActiveRevision.Revision}}</strong></span><span>{{tr .Lang "automation_activated"}} <time>{{displayTime $.Lang .ActiveRevision.ActivatedAt.UTC false}}</time></span>{{else}}<span>{{tr .Lang "automation_no_revision"}}</span>{{end}}</div></div><div class="automation-hero-action">{{if .CanOperate}}{{if .ActiveRevision}}<form method="post" action="/ui/tenants/{{.Tenant}}/billing-sync/pause" {{if not .ActiveRevision.Paused}}data-confirm-title="{{tr .Lang "automation_pause"}}" data-confirm-body="{{tr .Lang "confirm_pause_body"}}" data-confirm-target="#{{.ActiveRevision.Revision}}" data-confirm-action="{{tr .Lang "automation_pause"}}"{{end}}><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="stripe" value="{{.ActiveRevision.StripeID}}">{{if .ActiveRevision.Paused}}<button name="paused" value="false">{{tr .Lang "automation_resume"}}</button>{{else}}<button class="secondary" name="paused" value="true">{{tr .Lang "automation_pause"}}</button>{{end}}</form>{{else}}<a class="button" href="#automation-config">{{tr .Lang "automation_configure"}} ↓</a>{{end}}{{end}}</div></header>
<section class="workflow-flow" aria-label="{{tr .Lang "automation_flow_label"}}"><article class="flow-node"><div class="flow-node-head"><span class="flow-emblem stripe" aria-hidden="true">S</span><div><span class="flow-number">01 / {{tr $.Lang "automation_source"}}</span><h2>Stripe</h2></div></div><p>{{tr .Lang "automation_stripe_purpose"}}</p>{{if .ActiveRevision}}<code>{{connectionAccount .Lang .Connections .ActiveRevision.Config.StripeConnectionID}}</code>{{else}}<span class="flow-availability">{{if hasVerified .Connections "stripe"}}{{tr .Lang "automation_verified_available"}}{{else}}{{tr .Lang "automation_connection_needed"}}{{end}}</span>{{end}}</article><span class="flow-arrow" aria-hidden="true">→</span><article class="flow-node"><div class="flow-node-head"><span class="flow-emblem hubspot" aria-hidden="true">H</span><div><span class="flow-number">02 / {{tr $.Lang "automation_projection"}}</span><h2>HubSpot</h2></div></div><p>{{tr .Lang "automation_hubspot_purpose"}}</p>{{if .ActiveRevision}}<code>{{connectionAccount .Lang .Connections .ActiveRevision.Config.HubSpotConnectionID}}</code>{{else}}<span class="flow-availability">{{if hasVerified .Connections "hubspot"}}{{tr .Lang "automation_verified_available"}}{{else}}{{tr .Lang "automation_connection_needed"}}{{end}}</span>{{end}}</article><span class="flow-arrow" aria-hidden="true">→</span><article class="flow-node"><div class="flow-node-head"><span class="flow-emblem slack" aria-hidden="true">#</span><div><span class="flow-number">03 / {{tr $.Lang "automation_notification"}}</span><h2>Slack</h2></div></div><p>{{tr .Lang "automation_slack_purpose"}}</p>{{if .ActiveRevision}}<code>{{connectionAccount .Lang .Connections .ActiveRevision.Config.SlackConnectionID}}</code>{{else}}<span class="flow-availability">{{if hasVerified .Connections "slack"}}{{tr .Lang "automation_verified_available"}}{{else}}{{tr .Lang "automation_connection_needed"}}{{end}}</span>{{end}}</article></section>
<div class="automation-layout"><div class="automation-main"><section class="card studio-card" id="automation-config"><div class="section-head"><div><p class="eyebrow">{{tr .Lang "automation_configuration"}}</p><h2>{{if .ActiveRevision}}{{tr .Lang "automation_new_revision"}}{{else}}{{tr .Lang "automation_first_revision"}}{{end}}</h2><p class="muted">{{tr .Lang "automation_config_intro"}}</p></div><span class="range-chip">{{tr .Lang "automation_proposed_revision"}} #{{.NextRevision}}</span></div>{{if .CanOperate}}<form class="studio-form" method="post" action="/ui/tenants/{{.Tenant}}/billing-sync/preview"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><fieldset class="form-section"><legend><span>01</span> {{tr .Lang "automation_connected_accounts"}}</legend><p class="hint">{{tr .Lang "automation_verified_help"}} <a href="/ui/tenants/{{.Tenant}}/connections">{{tr .Lang "automation_manage_connections"}}</a></p><div class="form-grid three"><div class="form-field"><label for="stripe-choice">{{tr .Lang "automation_stripe_account"}}</label><select id="stripe-choice" name="stripe" required data-required-message="{{tr .Lang "automation_connection_required"}}" aria-describedby="stripe-help{{if index .FieldErrors "stripe"}} stripe-error{{end}}" {{if index .FieldErrors "stripe"}}aria-invalid="true"{{end}}><option value="" disabled {{if not .AutomationDraft.Stripe}}selected{{end}}>{{tr .Lang "automation_choose_stripe"}}</option>{{range .Connections}}{{if and (eq .Provider "stripe") (eq .Status "active") (eq .HealthStatus "verified") (eq .Mode "test") (or (eq .AuthState "") (eq .AuthState "ready"))}}<option value="{{.ID}}" {{if eq $.AutomationDraft.Stripe .ID}}selected{{end}}>{{.ProviderAccountID}} · {{tr $.Lang .Environment}}</option>{{end}}{{end}}</select><small class="field-help" id="stripe-help">{{tr .Lang "automation_stripe_help"}}</small>{{with index .FieldErrors "stripe"}}<span class="field-error" id="stripe-error" role="alert">{{tr $.Lang .}}</span>{{end}}</div><div class="form-field"><label for="hubspot-choice">{{tr .Lang "automation_hubspot_portal"}}</label><select id="hubspot-choice" name="hubspot" required data-required-message="{{tr .Lang "automation_connection_required"}}" aria-describedby="hubspot-help{{if index .FieldErrors "hubspot"}} hubspot-error{{end}}" {{if index .FieldErrors "hubspot"}}aria-invalid="true"{{end}}><option value="" disabled {{if not .AutomationDraft.HubSpot}}selected{{end}}>{{tr .Lang "automation_choose_hubspot"}}</option>{{range .Connections}}{{if and (eq .Provider "hubspot") (eq .Status "active") (eq .HealthStatus "verified") (eq .Mode "test") (or (eq .AuthState "") (eq .AuthState "ready"))}}<option value="{{.ID}}" {{if eq $.AutomationDraft.HubSpot .ID}}selected{{end}}>{{.ProviderAccountID}} · {{tr $.Lang .Environment}}</option>{{end}}{{end}}</select><small class="field-help" id="hubspot-help">{{tr .Lang "automation_hubspot_help"}}</small>{{with index .FieldErrors "hubspot"}}<span class="field-error" id="hubspot-error" role="alert">{{tr $.Lang .}}</span>{{end}}</div><div class="form-field"><label for="slack-choice">{{tr .Lang "automation_slack_workspace"}}</label><select id="slack-choice" name="slack" required data-required-message="{{tr .Lang "automation_connection_required"}}" aria-describedby="slack-help{{if index .FieldErrors "slack"}} slack-error{{end}}" {{if index .FieldErrors "slack"}}aria-invalid="true"{{end}}><option value="" disabled {{if not .AutomationDraft.Slack}}selected{{end}}>{{tr .Lang "automation_choose_slack"}}</option>{{range .Connections}}{{if and (eq .Provider "slack") (eq .Status "active") (eq .HealthStatus "verified") (eq .Mode "test") (or (eq .AuthState "") (eq .AuthState "ready"))}}<option value="{{.ID}}" {{if eq $.AutomationDraft.Slack .ID}}selected{{end}}>{{.ProviderAccountID}} · {{tr $.Lang .Environment}}</option>{{end}}{{end}}</select><small class="field-help" id="slack-help">{{tr .Lang "automation_slack_help"}}</small>{{with index .FieldErrors "slack"}}<span class="field-error" id="slack-error" role="alert">{{tr $.Lang .}}</span>{{end}}</div></div></fieldset><fieldset class="form-section"><legend><span>02</span> {{tr .Lang "automation_business_rules"}}</legend><div class="form-grid"><div class="form-field"><label for="prices">{{tr .Lang "automation_prices"}}</label><textarea id="prices" name="prices" rows="5" required spellcheck="false" placeholder="price_123&#10;price_456" aria-describedby="prices-help{{if index .FieldErrors "prices"}} prices-error{{end}}" {{if index .FieldErrors "prices"}}aria-invalid="true"{{end}}>{{.AutomationDraft.Prices}}</textarea><small class="field-help" id="prices-help">{{tr .Lang "automation_prices_help"}}</small>{{with index .FieldErrors "prices"}}<span class="field-error" id="prices-error" role="alert">{{tr $.Lang .}}</span>{{end}}</div><div class="form-field"><label for="channel">{{tr .Lang "automation_channel"}}</label><input id="channel" name="channel" value="{{.AutomationDraft.Channel}}" pattern="[CG][A-Z0-9]+" placeholder="C0123456789" required spellcheck="false" aria-describedby="channel-help{{if index .FieldErrors "channel"}} channel-error{{end}}" {{if index .FieldErrors "channel"}}aria-invalid="true"{{end}}><small class="field-help" id="channel-help">{{tr .Lang "automation_channel_help"}}</small>{{with index .FieldErrors "channel"}}<span class="field-error" id="channel-error" role="alert">{{tr $.Lang .}}</span>{{end}}</div></div><div class="form-field"><label for="policy">{{tr .Lang "automation_policy"}}</label><select id="policy" name="policy" required aria-describedby="policy-help{{if index .FieldErrors "policy"}} policy-error{{end}}" {{if index .FieldErrors "policy"}}aria-invalid="true"{{end}}><option value="explicit_only" {{if eq .AutomationDraft.Policy "explicit_only"}}selected{{end}}>{{tr .Lang "policy_explicit_only"}}</option><option value="unique_upsert" {{if eq .AutomationDraft.Policy "unique_upsert"}}selected{{end}}>{{tr .Lang "policy_unique_upsert"}}</option></select><small class="field-help" id="policy-help">{{tr .Lang "automation_policy_help"}}</small>{{with index .FieldErrors "policy"}}<span class="field-error" id="policy-error" role="alert">{{tr $.Lang .}}</span>{{end}}</div></fieldset><div class="form-actions"><p>{{tr .Lang "automation_review_note"}}</p><button type="submit">{{tr .Lang "automation_review_button"}} →</button></div></form>{{else}}<p class="muted">{{tr .Lang "automation_viewer_notice"}}</p>{{end}}</section>{{if .Revisions}}<section class="card revision-history"><div class="section-head"><h2>{{tr .Lang "automation_revision_history"}}</h2><span class="range-chip">{{len .Revisions}} {{tr .Lang "automation_recent_revisions"}}</span></div><div class="revision-list">{{range .Revisions}}<article><div><strong>#{{.Revision}}</strong><span class="badge {{.Status}}">{{tr $.Lang (status .Status)}}</span>{{if .Paused}}<span class="badge paused">{{tr $.Lang "Paused"}}</span>{{end}}<small>{{tr $.Lang "automation_activated"}} {{displayTime $.Lang .ActivatedAt.UTC false}}</small></div><p>{{tr $.Lang "automation_stripe_account"}} <code>{{connectionAccount $.Lang $.Connections .StripeID}}</code> · {{tr $.Lang "automation_prices"}} {{len .Config.TrackedPriceIDs}}</p></article>{{end}}</div></section>{{end}}</div><aside class="automation-aside"><section class="card contract-card"><p class="eyebrow">{{tr .Lang "automation_contract"}}</p><h2>{{tr .Lang "automation_safe_by_design"}}</h2><ul><li>{{tr .Lang "automation_warning_multiple"}}</li><li>{{tr .Lang "automation_warning_new_events"}}</li><li>{{tr .Lang "automation_warning_historical"}}</li><li>{{tr .Lang "automation_warning_identity"}}</li></ul><details><summary>{{tr .Lang "automation_managed_fields"}}</summary><p>{{tr .Lang "automation_fields_help"}}</p><ul>{{range .ManagedProperties}}<li><code>{{.}}</code></li>{{end}}</ul></details></section></aside></div>
{{template "bottom" .}}{{end}}

{{define "automation_preview"}}{{template "top" .}}<header class="page-heading"><p class="eyebrow">{{tr .Lang "automation_review_eyebrow"}}</p><h1>{{tr .Lang "automation_review_title"}}</h1><p class="lead">{{tr .Lang "automation_review_intro"}}</p></header><div class="review-layout"><section class="card review-card"><div class="section-head"><h2>{{tr .Lang "automation_review_summary"}}</h2><span class="badge verified">{{tr .Lang "automation_test_mode"}}</span></div><dl class="review-list"><dt>{{tr .Lang "automation_proposed_revision"}}</dt><dd>#{{.NextRevision}} <small>{{tr .Lang "automation_revision_provisional"}}</small></dd><dt>{{tr .Lang "automation_stripe_account"}}</dt><dd>{{connectionAccount .Lang .Connections .Detail.Config.StripeConnectionID}}<br><code>{{.Detail.Config.StripeConnectionID}}</code></dd><dt>{{tr .Lang "automation_hubspot_portal"}}</dt><dd>{{connectionAccount .Lang .Connections .Detail.Config.HubSpotConnectionID}}<br><code>{{.Detail.Config.HubSpotConnectionID}}</code></dd><dt>{{tr .Lang "automation_slack_workspace"}}</dt><dd>{{connectionAccount .Lang .Connections .Detail.Config.SlackConnectionID}}<br><code>{{.Detail.Config.SlackConnectionID}}</code></dd><dt>{{tr .Lang "automation_channel"}}</dt><dd><code>{{.Detail.Config.SlackChannelID}}</code></dd><dt>{{tr .Lang "automation_prices"}}</dt><dd class="price-pills">{{range .Detail.Config.TrackedPriceIDs}}<code>{{.}}</code>{{end}}</dd><dt>{{tr .Lang "automation_policy"}}</dt><dd>{{policyLabel .Lang .Detail.Config.CreationPolicy}}</dd></dl><div class="review-actions"><form method="post" action="/ui/tenants/{{.Tenant}}/billing-sync" data-confirm-title="{{tr .Lang "automation_activate"}}" data-confirm-body="{{tr .Lang "confirm_activate_body"}}" data-confirm-target="#{{.NextRevision}}" data-confirm-action="{{tr .Lang "automation_activate"}}"><input type="hidden" name="csrf_token" value="{{.CSRF}}"><input type="hidden" name="stripe" value="{{.Detail.Config.StripeConnectionID}}"><input type="hidden" name="hubspot" value="{{.Detail.Config.HubSpotConnectionID}}"><input type="hidden" name="slack" value="{{.Detail.Config.SlackConnectionID}}"><input type="hidden" name="channel" value="{{.Detail.Config.SlackChannelID}}"><input type="hidden" name="prices" value="{{join .Detail.Config.TrackedPriceIDs}}"><input type="hidden" name="policy" value="{{.Detail.Config.CreationPolicy}}"><button>{{tr .Lang "automation_activate"}}</button></form><a class="button secondary" href="/ui/tenants/{{.Tenant}}/billing-sync">{{tr .Lang "automation_edit_setup"}}</a></div></section><aside class="card review-contract"><h2>{{tr .Lang "automation_expected_behavior"}}</h2><ol><li>{{tr .Lang "automation_stripe_purpose"}}</li><li>{{tr .Lang "automation_hubspot_purpose"}}</li><li>{{tr .Lang "automation_slack_purpose"}}</li></ol><h3>{{tr .Lang "automation_exceptions"}}</h3><ul><li>{{tr .Lang "automation_warning_multiple"}}</li><li>{{tr .Lang "automation_warning_new_events"}}</li><li>{{tr .Lang "automation_warning_historical"}}</li><li>{{tr .Lang "automation_warning_unknown"}}</li></ul></aside></div>{{template "bottom" .}}{{end}}

{{define "runs"}}{{template "top" .}}<div id="runs-content"><header class="runs-hero"><div><p class="eyebrow">{{tr .Lang "runs_eyebrow"}}</p><h1>{{tr .Lang "runs_title"}}</h1><p class="lead">{{tr .Lang "runs_intro"}}</p></div><span class="range-chip">{{tr .Lang "runs_total"}} {{.RunTotal}}</span></header><section class="runs-summary" aria-label="{{tr .Lang "runs_summary"}}"><div class="runs-summary-item"><span class="runs-summary-icon success" aria-hidden="true">✓</span><div><strong>{{index .RunCounts "succeeded"}}</strong><small>{{tr .Lang "Succeeded"}}</small></div></div><div class="runs-summary-item"><span class="runs-summary-icon pending" aria-hidden="true">↻</span><div><strong>{{runFilterCount .RunCounts "in_progress"}}</strong><small>{{tr .Lang "Pending / running"}}</small></div></div><div class="runs-summary-item"><span class="runs-summary-icon warning" aria-hidden="true">!</span><div><strong>{{index .RunCounts "needs_attention"}}</strong><small>{{tr .Lang "Needs attention"}}</small></div></div><div class="runs-summary-item"><span class="runs-summary-icon unknown" aria-hidden="true">?</span><div><strong>{{index .RunCounts "unknown"}}</strong><small>{{tr .Lang "Outcome unknown"}}</small></div></div></section><div class="runs-toolbar"><div><h2>{{tr .Lang "runs_activity"}}</h2><p>{{tr .Lang "runs_filter_help"}}</p></div><span class="runs-page-size">{{tr .Lang "runs_page_size"}}</span></div><nav class="filters runs-filters" aria-label="{{tr .Lang "runs_status_filters"}}">{{range .Filters}}<a href="/ui/tenants/{{$.Tenant}}/runs{{if .Key}}?status={{.Key}}{{end}}" hx-get="/ui/tenants/{{$.Tenant}}/runs{{if .Key}}?status={{.Key}}{{end}}" hx-select="#runs-content" hx-target="#runs-content" hx-push-url="true" {{if eq $.Filter .Key}}aria-current="page"{{end}}>{{tr $.Lang .Label}} <span>{{runFilterCount $.RunCounts .Key}}</span></a>{{end}}</nav><p class="runs-request-status" id="runs-request-status" role="status" aria-live="polite" aria-atomic="true"><span class="runs-loading">{{tr .Lang "runs_loading"}}</span><span class="runs-error">{{tr .Lang "runs_request_error"}}</span><span class="runs-auth">{{tr .Lang "runs_auth_expired"}} <a href="/auth/login">{{tr .Lang "ui_error_signin_action"}}</a></span></p>{{if .Runs}}<div class="run-list" role="list">{{range .Runs}}<article class="run-row" role="listitem"><div class="run-event"><span class="run-event-icon {{.Status}}" aria-hidden="true">{{if eq .Status "succeeded"}}✓{{else if eq .Status "unknown"}}?{{else if eq .Status "retry_wait"}}↻{{else if eq .Status "dead"}}×{{else if eq .Status "needs_attention"}}!{{else}}•{{end}}</span><div><a href="/ui/tenants/{{$.Tenant}}/runs/{{.ID}}">{{.EventType}} <span aria-hidden="true">↗</span></a><small><code>{{.EventID}}</code></small></div></div><div class="run-identity"><small>{{tr $.Lang "runs_business_identity"}}</small>{{if .CustomerID}}<span>{{tr $.Lang "runs_customer"}} <code>{{.CustomerID}}</code></span>{{end}}{{if .InvoiceID}}<span>{{tr $.Lang "runs_invoice"}} <code>{{.InvoiceID}}</code></span>{{end}}{{if and (not .CustomerID) (not .InvoiceID)}}<span>{{tr $.Lang "runs_not_recorded"}}</span>{{end}}</div><div class="run-progress"><span class="badge {{.Status}}">{{tr $.Lang (status .Status)}}</span><small>{{tr $.Lang (runStep .)}}</small><span class="run-status-help">{{tr $.Lang (runStatusHelp .Status)}}</span></div><div class="run-time"><time>{{displayTime $.Lang .CreatedAt.UTC false}}</time><small>{{tr $.Lang "runs_attempts"}} {{.Attempts}}</small></div></article>{{end}}</div>{{else}}{{if eq .RunTotal 0}}<section class="card runs-empty"><span class="empty-icon" aria-hidden="true">◇</span><h2>{{tr .Lang "runs_empty_title"}}</h2><p>{{tr .Lang "runs_empty_body"}}</p><a class="button secondary" href="/ui/tenants/{{.Tenant}}/billing-sync">{{tr .Lang "runs_open_automation"}}</a></section>{{else}}<section class="card runs-empty"><span class="empty-icon" aria-hidden="true">○</span><h2>{{tr .Lang "runs_filtered_empty_title"}}</h2><p>{{tr .Lang "runs_filtered_empty_body"}}</p><a class="button secondary" href="/ui/tenants/{{.Tenant}}/runs" hx-get="/ui/tenants/{{.Tenant}}/runs" hx-select="#runs-content" hx-target="#runs-content" hx-push-url="true">{{tr .Lang "runs_clear_filter"}}</a></section>{{end}}{{end}}{{if .NextCursor}}<nav class="runs-pagination" aria-label="{{tr .Lang "runs_pagination"}}"><span>{{tr .Lang "runs_newest_first"}}</span><a class="button secondary" href="/ui/tenants/{{.Tenant}}/runs?status={{.Filter}}&cursor={{.NextCursor}}" hx-get="/ui/tenants/{{.Tenant}}/runs?status={{.Filter}}&cursor={{.NextCursor}}" hx-select="#runs-content" hx-target="#runs-content" hx-push-url="true">{{tr .Lang "runs_older"}} →</a></nav>{{end}}</div>{{template "bottom" .}}{{end}}
`
